mapper.select:
select

from platform_alert_event

  and cluster_id = #{clusterId,jdbcType=VARCHAR}


    and `namespace` in
    #{ns}


    and 1 = 0

  and `status` = #{status,jdbcType=VARCHAR}
  and severity = #{severity,jdbcType=VARCHAR}
  and `namespace` = #{namespace,jdbcType=VARCHAR}
  and alertname like concat('%', #{alertname,jdbcType=VARCHAR}, '%')
  and alertname <> 'Watchdog'
  and starts_at >= #{from,jdbcType=TIMESTAMP}
  and starts_at < #{to,jdbcType=TIMESTAMP}

    and (starts_at < #{cursorStartsAt,jdbcType=TIMESTAMP}
         or (starts_at = #{cursorStartsAt,jdbcType=TIMESTAMP} and id < #{cursorId,jdbcType=BIGINT}))


order by starts_at desc, id desc
limit #{limit,jdbcType=INTEGER}

select id from platform_alert_event
where cluster_id = #{clusterId,jdbcType=VARCHAR}
  and alertname = #{alertname,jdbcType=VARCHAR}
order by id desc
limit 20
